effect.shader:
void main() {
    vec2 uv = acScreenNorm;

    // Curvatura de tubo: empurra as bordas para fora a partir do centro.
    if (curvature > 0.0) {
        vec2 centered = uv * 2.0 - 1.0;
        vec2 offset = centered.yx * centered.yx * centered * curvature;
        uv = (centered + offset) * 0.5 + 0.5;

        // Fora do tubo não há imagem. Preto opaco, e não transparente: uma TV
        // desligada tem moldura, não tem buraco.
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
            fragColor = vec4(0.0, 0.0, 0.0, 1.0);
            return;
        }
    }

    // Sangramento: os três canhões de cor do tubo nunca alinhavam direito.
    vec2 shift = vec2(bleed * acEscalaDePixel, 0.0) * acTexelSize;
    vec4 base = texture(inputImg, uv);
    float r = texture(inputImg, uv + shift).r;
    float b = texture(inputImg, uv - shift).b;
    vec3 rgb = vec3(r, base.g, b);

    // Linhas de varredura.
    float line = sin(uv.y * scanlines * 3.14159265);
    rgb *= 1.0 - scanDepth * (0.5 + 0.5 * line) * 0.5;

    // Tremida do sincronismo vertical, ligada ao tempo.
    rgb *= 1.0 - flicker * (0.5 + 0.5 * sin(acTime * 47.0));

    // Vinheta do tubo.
    vec2 fromCenter = (uv - 0.5) * 2.0;
    float dist = length(fromCenter * vec2(acAspect, 1.0));
    rgb *= 1.0 - vignette * smoothstep(0.6, 1.6, dist);

    fragColor = vec4(clamp(rgb, 0.0, 1.0), base.a);
}
